from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'runtime' / 'assembly'
OUT.mkdir(parents=True, exist_ok=True)
ALL = "Stone-Zsela, Stevens, O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer"
ASSOC = "Stevens, O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer"
commitments = (ROOT/'freeze/OT_1996CHUNK1_COMMITMENTS_B.md').read_text(encoding='utf-8')
reconciliation = (ROOT/'freeze/OT_1996CHUNK1_RECONCILED_B_REPAIRS_VALIDATED.md').read_text(encoding='utf-8')

def bounded_case(text, number):
    m = re.search(rf'^## {number}\. .*?(?=^## |\Z)', text, re.M|re.S)
    if not m: raise ValueError(number)
    return m.group(0).strip()

def holding(title, rule, authority, explanation, limits=''):
    assert len(explanation.split()) <= 350, (title, len(explanation.split()))
    return '\n\n'.join(x for x in [f'### {title}', '**Holding and operative rule:** '+rule, '**Authority:** '+authority, '**Controlling explanation:** '+explanation, ('**Limits and questions not reached:** '+limits) if limits else ''])

